    pub(crate) fn mark_var_moved_checked(
        &mut self,
        id: DefId,
        name: Symbol,
        reason: MoveReason,
        at: crate::ast::Span,
    ) -> Result<(), String> {
        if let Some(defer_span) = self.defer_read_vars.get(&id) {
            return Err(format!(
                "{}: cannot move `{}`: it is read by the `defer` registered at {}; \
                 move it before the defer is registered, or clone it into the defer",
                at.loc(),
