fn unknown_constructor_is_rejected() {
    let c = compile("*main\n    x is TotallyUndefinedThing()\n    log('ok')\n");
    assert!(!c.ok(), "unknown constructor must not compile");
    assert!(
        c.stderr().contains("unknown type or variant"),
